            data[i] = Math.random() * 2 - 1;
        }

        const noise = this.ctx.createBufferSource();
        noise.buffer = buffer;

        const filter = this.ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.setValueAtTime(300, now);
        filter.frequency.exponentialRampToValueAtTime(1400, now + 0.6);
        filter.frequency.exponentialRampToValueAtTime(200, now + 1.4);
        filter.Q.value = 3.0;

        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(0.01, now);
        gain.gain.linearRampToValueAtTime(0.4 * this.volume, now + 0.5);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 1.45);

        noise.connect(filter);
        filter.connect(gain);
        gain.connect(this.ctx.destination);

        noise.start(now);
        noise.stop(now + 1.5);
    }

    // 7. Âm thanh chuông tiếp viên "Ding-Dong" quen thuộc trên khoang
    playCabinChime() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;

        // Nốt High: F5 (698.46Hz)
        const osc1 = this.ctx.createOscillator();
        const gain1 = this.ctx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(698.46, now);
        gain1.gain.setValueAtTime(0.25 * this.volume, now);
        gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.9);
        osc1.connect(gain1);
        gain1.connect(this.ctx.destination);
        osc1.start(now);
        osc1.stop(now + 0.95);

        // Nốt Low: C#5 (554.37Hz) hoặc Db5
        const osc2 = this.ctx.createOscillator();
        const gain2 = this.ctx.createGain();
        osc2.type = 'sine';
        osc2.frequency.setValueAtTime(554.37, now + 0.45);
        gain2.gain.setValueAtTime(0.25 * this.volume, now + 0.45);
        gain2.gain.exponentialRampToValueAtTime(0.001, now + 1.5);
        osc2.connect(gain2);
        gain2.connect(this.ctx.destination);
        osc2.start(now + 0.45);
        osc2.stop(now + 1.55);
    }

    // 8. Động cơ máy bay êm ái (Giúp trẻ làm quen âm thanh cabin không bị giật mình)
    startEngineSound(level = 0.25) {
        if (this.isEngineRunning || this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        try {
            const bufferSize = this.ctx.sampleRate * 2;
            const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
            const data = buffer.getChannelData(0);
            let lastOut = 0.0;
            // Pink noise lọc êm
            for (let i = 0; i < bufferSize; i++) {
                const white = Math.random() * 2 - 1;
                data[i] = (lastOut + (0.02 * white)) / 1.02;
                lastOut = data[i];
                data[i] *= 3.5;
            }

            this.engineSource = this.ctx.createBufferSource();
            this.engineSource.buffer = buffer;
            this.engineSource.loop = true;

            const filter = this.ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.value = 160; // Chỉ giữ âm trầm êm ái
            filter.Q.value = 1.2;

            // Thêm chút rung hum tần số thấp
            const droneOsc = this.ctx.createOscillator();
            droneOsc.type = 'sine';
            droneOsc.frequency.value = 85;

            this.engineGain = this.ctx.createGain();
            this.engineGain.gain.setValueAtTime(0.001, this.ctx.currentTime);
            this.engineGain.gain.linearRampToValueAtTime(level * this.volume, this.ctx.currentTime + 1.0);

            this.engineSource.connect(filter);
            filter.connect(this.engineGain);
            droneOsc.connect(this.engineGain);
            this.engineGain.connect(this.ctx.destination);

            this.engineSource.start();
            droneOsc.start();
            this.engineDrone = droneOsc;
            this.isEngineRunning = true;
        } catch (e) {
            console.warn('Engine sound error:', e);
        }
    }

    stopEngineSound() {
        if (!this.isEngineRunning || !this.engineGain) return;
        try {
            const now = this.ctx.currentTime;
            this.engineGain.gain.linearRampToValueAtTime(0.001, now + 0.5);
            setTimeout(() => {
                if (this.engineSource) {
                    this.engineSource.stop();
                    this.engineSource.disconnect();
                }
                if (this.engineDrone) {
                    this.engineDrone.stop();
                    this.engineDrone.disconnect();
                }
                this.isEngineRunning = false;
            }, 550);
        } catch (e) {
            this.isEngineRunning = false;
        }
    }

    setEngineVolume(level) {
        if (this.engineGain && this.isEngineRunning) {
            this.engineGain.gain.setValueAtTime(level * this.volume, this.ctx.currentTime);
        }
    }

    // 9. Âm thanh pháo hoa & chúc mừng chiến thắng (Fanfare)
    playFanfare() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const notes = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6
        const times = [0, 0.15, 0.3, 0.5];
        const durations = [0.18, 0.18, 0.18, 0.8];

        notes.forEach((freq, idx) => {
            const t = now + times[idx];
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();

            osc.type = 'triangle';
            osc.frequency.setValueAtTime(freq, t);

            gain.gain.setValueAtTime(0.3 * this.volume, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + durations[idx]);

            osc.connect(gain);
            gain.connect(this.ctx.destination);

            osc.start(t);
            osc.stop(t + durations[idx] + 0.05);
        });
    }

    // 10. Âm thanh nổ bong bóng nhẹ khi chạm nút
    playPop() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(500, now);
        osc.frequency.exponentialRampToValueAtTime(80, now + 0.08);

        gain.gain.setValueAtTime(0.25 * this.volume, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now);
        osc.stop(now + 0.09);
    }

    // --- VOICE-OVER & SPEECH GUIDANCE SYSTEM (Tiếng Việt truyền cảm) ---
    speak(text, onComplete) {
        if (!this.voiceEnabled) {
            if (onComplete) onComplete();
            return;
        }

        // Cập nhật bong bóng thoại nhân vật mascot trên UI nếu có
        this.showSpeechBubble(text);

        if (!('speechSynthesis' in window)) {
            if (onComplete) setTimeout(onComplete, 2000);
            return;
        }

        window.speechSynthesis.cancel();

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'vi-VN';
        utterance.rate = 0.92; // Tốc độ đọc chậm rãi, rõ ràng cho bé 3-4 tuổi
        utterance.pitch = 1.15; // Giọng hơi cao nhẹ, ấm áp, thân thiện

        // Tìm voice tiếng Việt nếu trình duyệt hỗ trợ
        const voices = window.speechSynthesis.getVoices();
        const viVoice = voices.find(v => v.lang.includes('vi') || v.name.includes('Vietnamese') || v.name.includes('An') || v.name.includes('Linh'));
        if (viVoice) {
            utterance.voice = viVoice;
        }

        utterance.onend = () => {
            if (onComplete) onComplete();
        };
        utterance.onerror = () => {
            if (onComplete) onComplete();
        };

        window.speechSynthesis.speak(utterance);
    }

    showSpeechBubble(text) {
        const bubble = document.getElementById('mascot-speech-bubble');
        const textSpan = document.getElementById('mascot-speech-text');
        const mascot = document.getElementById('mascot-guide');

        if (bubble && textSpan) {
            textSpan.textContent = text;
            bubble.classList.remove('hidden');
            bubble.classList.add('pop-in');

            if (mascot) {
                mascot.classList.add('mascot-talking');
            }

            clearTimeout(this.bubbleTimer);
            this.bubbleTimer = setTimeout(() => {
                bubble.classList.remove('pop-in');
                bubble.classList.add('pop-out');
                if (mascot) mascot.classList.remove('mascot-talking');
                setTimeout(() => {
                    bubble.classList.add('hidden');
                    bubble.classList.remove('pop-out');
                }, 300);
            }, Math.max(3500, text.length * 110));
        }
    }
}

