/**
 * effects.js - Canvas Particle System, Fireworks, Confetti & Sparkles
 * Tối ưu hóa hiệu ứng 60fps cho thiết bị di động & tablet
 */

class KidEffectsManager {
    constructor() {
        this.canvas = null;
        this.ctx = null;
        this.particles = [];
        this.fireworks = [];
        this.animationFrame = null;
        this.isRunning = false;
    }

    init() {
        this.canvas = document.getElementById('effects-canvas');
        if (!this.canvas) return;
        this.ctx = this.canvas.getContext('2d');
        this.resize();
        window.addEventListener('resize', () => this.resize());
    }

    resize() {
        if (!this.canvas) return;
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
    }

    // 1. Pháo hoa & Confetti toàn màn hình khi chiến thắng
    startCelebrationFireworks(durationMs = 6000) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        this.particles = [];
        this.fireworks = [];
        this.isRunning = true;

        const colors = [
            '#FF5252', '#FF4081', '#E040FB', '#7C4DFF', 
            '#536DFE', '#40C4FF', '#18FFFF', '#64FFDA', 
            '#69F0AE', '#B2FF59', '#EEFF41', '#FFFF00', 
            '#FFD740', '#FFAB40', '#FF6E40'
        ];

        let fireworkTimer = setInterval(() => {
            if (!this.isRunning) {
                clearInterval(fireworkTimer);
                return;
            }
            const x = Math.random() * this.canvas.width * 0.8 + this.canvas.width * 0.1;
            const y = Math.random() * this.canvas.height * 0.5 + this.canvas.height * 0.1;
            this.createFireworkBurst(x, y, colors);
            if (window.audioMgr) {
                window.audioMgr.playTing();
            }
        }, 500);

        // Thả confetti từ trên xuống
        for (let i = 0; i < 70; i++) {
            this.particles.push({
                x: Math.random() * this.canvas.width,
                y: -Math.random() * this.canvas.height,
                vx: (Math.random() - 0.5) * 3,
                vy: Math.random() * 3 + 2,
                size: Math.random() * 10 + 8,
                color: colors[Math.floor(Math.random() * colors.length)],
                rotation: Math.random() * 360,
                vRot: (Math.random() - 0.5) * 10,
                shape: Math.random() > 0.4 ? 'rect' : 'star',
                alpha: 1
            });
        }

        this.loop();

        setTimeout(() => {
            clearInterval(fireworkTimer);
            setTimeout(() => {
                this.stop();
            }, 3000);
        }, durationMs);
    }

    createFireworkBurst(x, y, colors) {
        const count = 45;
        for (let i = 0; i < count; i++) {
            const angle = (Math.PI * 2 / count) * i + (Math.random() * 0.2);
            const speed = Math.random() * 6 + 3;
            this.particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                size: Math.random() * 7 + 4,
                color: colors[Math.floor(Math.random() * colors.length)],
                alpha: 1,
                decay: Math.random() * 0.02 + 0.015,
                gravity: 0.08,
                shape: 'circle'
            });
        }
    }

    // 2. Chùm sao sáng tức thì tại vị trí chạm / kéo thả đúng
    burstStarsAt(x, y) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        const starColors = ['#FFD700', '#FFA500', '#FF69B4', '#00E5FF', '#76FF03'];
        for (let i = 0; i < 22; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = Math.random() * 5 + 2;
            this.particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed - 1.5,
                size: Math.random() * 8 + 6,
                color: starColors[Math.floor(Math.random() * starColors.length)],
                alpha: 1,
                decay: 0.03,
                gravity: 0.1,
                shape: 'star',
                rotation: Math.random() * 360,
                vRot: (Math.random() - 0.5) * 15
            });
        }

        if (!this.isRunning) {
            this.isRunning = true;
            this.loop();
        }
    }

    loop() {
        if (!this.isRunning) return;

        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];
            p.x += p.vx;
            p.y += p.vy;
            if (p.gravity) p.vy += p.gravity;
            if (p.decay) p.alpha -= p.decay;
            if (p.vRot) p.rotation += p.vRot;

            if (p.alpha <= 0 || p.y > this.canvas.height + 20) {
                this.particles.splice(i, 1);
                continue;
            }

            this.ctx.save();
            this.ctx.globalAlpha = Math.max(0, p.alpha);
            this.ctx.fillStyle = p.color;

            if (p.shape === 'star') {
                this.drawStar(p.x, p.y, 5, p.size, p.size / 2, (p.rotation || 0) * Math.PI / 180);
            } else if (p.shape === 'rect') {
                this.ctx.translate(p.x, p.y);
                this.ctx.rotate((p.rotation || 0) * Math.PI / 180);
                this.ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
            } else {
                this.ctx.beginPath();
                this.ctx.arc(p.x, p.y, p.size / 2, 0, Math.PI * 2);
                this.ctx.fill();
            }

            this.ctx.restore();
        }

        if (this.particles.length > 0) {
            this.animationFrame = requestAnimationFrame(() => this.loop());
        } else {
            this.isRunning = false;
        }
    }

    drawStar(cx, cy, spikes, outerRadius, innerRadius, angleOffset = 0) {
        let rot = Math.PI / 2 * 3 + angleOffset;
        let x = cx;
        let y = cy;
        const step = Math.PI / spikes;

        this.ctx.beginPath();
        this.ctx.moveTo(cx, cy - outerRadius);
        for (let i = 0; i < spikes; i++) {
            x = cx + Math.cos(rot) * outerRadius;
            y = cy + Math.sin(rot) * outerRadius;
            this.ctx.lineTo(x, y);
            rot += step;

            x = cx + Math.cos(rot) * innerRadius;
            y = cy + Math.sin(rot) * innerRadius;
            this.ctx.lineTo(x, y);
            rot += step;
        }
        this.ctx.lineTo(cx, cy - outerRadius);
        this.ctx.closePath();
        this.ctx.fill();
    }

    stop() {
        this.isRunning = false;
        if (this.animationFrame) {
            cancelAnimationFrame(this.animationFrame);
        }
        if (this.ctx && this.canvas) {
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
        }
        this.particles = [];
    }
}

